import fs from 'node:fs';
import path from 'node:path';
import Database from 'better-sqlite3';
import { drizzle, type BetterSQLite3Database } from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import { config } from '../config';
import * as schema from './schema';

export type DB = BetterSQLite3Database<typeof schema> & { $client: Database.Database };

/** Directory with SQL migrations generated by drizzle-kit. */
const MIGRATIONS_DIR = process.env.MIGRATIONS_DIR ?? path.resolve('drizzle');

/** Opens (creating if needed) a database file and applies all pending migrations. */
export function openDatabase(file: string): DB {
	if (file !== ':memory:') fs.mkdirSync(path.dirname(file), { recursive: true });
	const sqlite = new Database(file);
	sqlite.pragma('journal_mode = WAL');
	sqlite.pragma('foreign_keys = ON');
	sqlite.pragma('busy_timeout = 5000');
	const db = drizzle(sqlite, { schema });
	migrate(db, { migrationsFolder: MIGRATIONS_DIR });
	return db;
}

let instance: DB | undefined;

/** The application database in `DATA_DIR/app.db`. */
export function db(): DB {
	instance ??= openDatabase(path.join(config().dataDir, 'app.db'));
	return instance;
}

export { schema };
